// План specs/invoices.md 3.3 (кейс .qa/tests/invoices/IN-07). PROD, admin, компания «test», десктоп.
// @writes @data: один счёт (QA-unit client, $1, позиция «QA-AUTO a901 409 …»); прямой PATCH его номера на занятый
// (таблица Invoice в Supabase REST, токен — сохранённая сессия страницы). Чужие счета только читаются. В конце — Actions → Delete.
import { test, expect } from '../../fixtures';
import { supabaseSession } from '../audit-log/audit-helpers';
import {
  PROD_CLIENT, PROD_ROLE, TEST_COMPANY_ID, addManualItem, openNewInvoiceProd, pickCustomer, prepareProdTest, removeDocumentAt, stamp,
  waitInvoiceCreated,
} from './invoice-helpers';

test.describe('Счета — номер нового счёта (#a901b1)', () => {
  test('QA-AUTO: changing an invoice number to a taken one is rejected with 409 invoice_number_taken #a901b1 @desktop @writes @data', async ({ asUser }) => {
    test.setTimeout(150_000);
    const page = await asUser(PROD_ROLE);
    await prepareProdTest(page);
    const mark = stamp();
    let invoiceUrl: string | null = null;
    try {
      await openNewInvoiceProd(page);
      await pickCustomer(page, PROD_CLIENT);
      await addManualItem(page, { name: `QA-AUTO a901 409 ${mark}`, price: '1' });
      await page.getByRole('button', { name: 'Create Invoice' }).click();
      const created = await waitInvoiceCreated(page);
      invoiceUrl = created.url;
      const id = new URL(created.url).searchParams.get('id') as string;

      const s = await supabaseSession(page);
      const h = { apikey: s.apikey, Authorization: `Bearer ${s.token}`, Accept: 'application/json' };

      // Занятый номер — любой другой счёт компании test (только чтение)
      const other = await page.request.get(
        `${s.base}/rest/v1/Invoice?select=id,invoice_number&company_id=eq.${TEST_COMPANY_ID}&invoice_number=like.INV-*&id=neq.${id}&invoice_number=neq.${created.number}&limit=1`,
        { headers: h },
      );
      expect(other.status(), 'GET другого счёта компании').toBe(200);
      const [taken] = (await other.json()) as { id: string; invoice_number: string }[];
      expect(taken?.invoice_number, 'в компании test есть другой счёт с номером INV-…').toMatch(/^INV-\d+$/);

      // Смена номера на занятый блокируется (коммент программиста 12.11; QA 12.11 — 409, hint invoice_number_taken)
      const patch = await page.request.patch(`${s.base}/rest/v1/Invoice?id=eq.${id}`, {
        headers: { ...h, 'Content-Type': 'application/json', Prefer: 'return=representation' },
        data: { invoice_number: taken.invoice_number },
      });
      expect(patch.status(), `PATCH номера на занятый ${taken.invoice_number}`).toBe(409);
      const err = (await patch.json().catch(() => ({}))) as { hint?: string };
      expect(err.hint, 'подсказка ошибки').toBe('invoice_number_taken');

      // Номер счёта не изменился
      const after = await page.request.get(`${s.base}/rest/v1/Invoice?select=invoice_number&id=eq.${id}`, { headers: h });
      expect(((await after.json()) as { invoice_number: string }[])[0]?.invoice_number, 'номер после отказа').toBe(created.number);
    } finally {
      await removeDocumentAt(page, invoiceUrl, `QA-AUTO a901 409 ${mark}`);
    }
  });
});
